"""Render a self-contained, read-only Workflow review page."""

from __future__ import annotations

import json
from typing import Any, Mapping

from .inspection_snapshot_definition import validate_workflow_review_bundle


def _embedded_json(bundle: Mapping[str, Any]) -> str:
    text = json.dumps(bundle, ensure_ascii=False, separators=(",", ":"))
    return text.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")


def render_workflow_review_html(bundle: Mapping[str, Any]) -> str:
    """Return one portable HTML file with no runtime or network dependency."""

    validate_workflow_review_bundle(bundle)
    payload = _embedded_json(bundle)
    return _HTML.replace("__WORKFLOW_REVIEW_BUNDLE__", payload)


_HTML = r'''<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="color-scheme" content="dark">
  <title>Agent Runtime Workflow Review</title>
  <style>
    :root{color-scheme:dark;--bg:#090d12;--panel:#10161d;--panel2:#151d26;--line:#25313d;--bright:#385066;--text:#e8eef5;--muted:#8fa0b2;--cyan:#55d8d1;--green:#7de0a6;--amber:#e9b95d;--red:#ff8794;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}*{box-sizing:border-box}body{margin:0;min-width:320px;background:var(--bg);color:var(--text)}button{color:inherit;font:inherit}.top{padding:16px 22px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;background:rgba(9,13,18,.97);z-index:3}.eyebrow{color:var(--cyan);font-size:10px;font-weight:750;letter-spacing:.14em;text-transform:uppercase}.muted{color:var(--muted)}.mono{font:11px/1.55 "SFMono-Regular",Consolas,monospace;overflow-wrap:anywhere}h1,h2,h3,p{margin:0}h1{font-size:21px}.shell{display:grid;grid-template-columns:270px minmax(0,1fr);gap:16px;padding:16px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:10px}.side{padding:14px;position:sticky;top:92px;height:calc(100vh - 108px);overflow:auto}.run{width:100%;text-align:left;border:1px solid var(--line);background:#0c1218;border-radius:8px;padding:11px;margin-top:8px;cursor:pointer}.run.active,.run:hover{border-color:var(--cyan);background:#111d23}.main{display:grid;gap:16px;min-width:0;align-content:start}.summary,.graph,.detail{padding:18px 20px}.summary{display:flex;justify-content:space-between;gap:18px}.metrics{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.metric{padding:8px 11px;min-width:88px;background:var(--panel2);border:1px solid var(--line);border-radius:7px}.metric span{display:block;color:var(--muted);font-size:9px;text-transform:uppercase}.metric strong{font-size:16px}.nodes{display:flex;gap:18px;overflow:auto;padding:18px 2px 10px}.node{position:relative;min-width:150px;border:1px solid var(--bright);border-radius:9px;background:#0b1218;padding:12px}.node:after{content:"→";position:absolute;right:-15px;top:26px;color:#516577}.node:last-child:after{display:none}.node h3{font-size:12px;margin:6px 0 10px}.occurrence{border:1px solid var(--line);background:var(--panel2);border-radius:5px;padding:5px 7px;font-size:9px;cursor:pointer}.occurrence.active{border-color:var(--cyan);color:var(--cyan)}.routes{display:flex;gap:7px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:12px}.route{font-size:9px;border:1px solid var(--line);border-radius:5px;padding:5px 7px}.tabs{display:flex;overflow:auto;border-bottom:1px solid var(--line);margin:14px -20px 0;padding:0 20px}.tabs button{border:0;border-bottom:2px solid transparent;background:none;color:var(--muted);padding:10px 12px;cursor:pointer}.tabs button.active{color:var(--cyan);border-color:var(--cyan)}.content{padding-top:16px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.card,details{background:#0b1218;border:1px solid var(--line);border-radius:8px;padding:11px}.wide{grid-column:1/-1}.card label{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;margin-bottom:5px}details{margin-bottom:8px}summary{cursor:pointer;font-weight:650}.status{border:1px solid rgba(125,224,166,.35);color:var(--green);border-radius:99px;padding:4px 8px;font-size:10px}.failed{color:var(--red);border-color:rgba(255,135,148,.35)}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#080c10;border:1px solid var(--line);border-radius:8px;color:#c9d8e6;padding:14px;font:11px/1.65 "SFMono-Regular",Consolas,monospace;max-height:62vh;overflow:auto}.empty{color:var(--muted);padding:14px 0}.note{color:var(--amber);border-left:2px solid var(--amber);padding-left:10px}@media(max-width:900px){.shell{grid-template-columns:1fr}.side{position:static;height:auto}.grid{grid-template-columns:1fr 1fr}}@media(max-width:620px){.shell{padding:10px}.summary{display:block}.metrics{justify-content:flex-start;margin-top:12px}.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header class="top"><div><p class="eyebrow">AGENT RUNTIME · READ ONLY</p><h1>Workflow Review</h1></div><div class="mono muted" id="bundle_id"></div></header>
  <main class="shell"><aside class="panel side"><p class="eyebrow">MODULE RUNS</p><h2>Execution history</h2><div id="run_list"></div></aside><section class="main"><section class="panel summary"><div><p class="eyebrow" id="workflow_release">WORKFLOW</p><h2 id="workflow_title"></h2><p class="mono muted" id="execution_id"></p></div><div class="metrics" id="metrics"></div></section><section class="panel graph"><p class="eyebrow">FROZEN WORKFLOW RELEASE</p><h2>Graph and occurrences</h2><div class="nodes" id="nodes"></div><div class="routes" id="routes"></div></section><section class="panel detail"><p class="eyebrow" id="selected_node">SELECT A MODULE RUN</p><h2 id="selected_run">Run details</h2><nav class="tabs" id="tabs"><button class="active" data-tab="overview">Overview</button><button data-tab="context">Context</button><button data-tab="attempts">Attempts</button><button data-tab="output">Output</button><button data-tab="decisions">Evaluation &amp; Resolution</button><button data-tab="raw">Raw records</button></nav><div class="content" id="content"></div></section></section></main>
  <script>
  "use strict";
  const bundle=__WORKFLOW_REVIEW_BUNDLE__;const inspection=bundle.inspection;let selected=inspection.modules[0]?.module_run?.module_run_id??null;let tab="overview";const el=id=>document.getElementById(id);const esc=value=>String(value??"unknown").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");const pretty=value=>esc(JSON.stringify(value,null,2));const contents=new Map(bundle.contents.map(row=>[row.content_ref,row]));
  function moduleById(){return inspection.modules.find(row=>row.module_run.module_run_id===selected)}function card(label,value,wide=false){return `<div class="card ${wide?"wide":""}"><label>${esc(label)}</label><div class="mono">${esc(value)}</div></div>`}function bodyFor(ref){if(!ref)return `<p class="empty">No recorded content reference.</p>`;const row=contents.get(ref);if(!row)return `<p class="note">${esc(ref)} is metadata-only in this export.</p>`;if(row.redaction_state!=="content_read_granted")return `<p class="note">${esc(row.redaction_reason)}</p>`;return `<pre>${typeof row.body==="string"?esc(row.body):pretty(row.body)}</pre>`}function attemptView(row){const starts=row.attempt_starts??[];const startByAttempt=new Map(starts.map(start=>[start.attempt_id,start]));const incomplete=starts.filter(start=>start.terminal_status===null).map(start=>`<details open><summary><span class="status ${start.lease_state==="expired"?"failed":""}">${esc(start.lease_state)}</span> ${esc(start.attempt_id)}</summary><div class="grid">${card("Started",start.recorded_at_utc,true)}${card("Deadline",start.deadline_at_utc,true)}</div></details>`).join("");const terminal=(row.attempts??[]).map(attempt=>`<details><summary><span class="status ${attempt.status==="failed"?"failed":""}">${esc(attempt.status)}</span> ${esc(attempt.attempt_id)}</summary><div class="grid">${card("Input tokens",attempt.input_tokens??"unknown")}${card("Output tokens",attempt.output_tokens??"unknown")}${card("Cache read",attempt.cache_read_tokens??"unknown")}${card("Failure",attempt.failure_class??"none",true)}${card("Recovery reason",startByAttempt.get(attempt.attempt_id)?.orphan_reason_code??"none",true)}</div>${attempt.failure_detail_ref?bodyFor(attempt.failure_detail_ref):""}</details>`).join("");return incomplete+terminal||'<p class="empty">No Attempt record.</p>'}
  function render(){const workflow=inspection.trace.workflow;const release=inspection.workflow_release;el("bundle_id").textContent=bundle.bundle_id;el("workflow_release").textContent=release?`${release.workflow_id} · ${release.workflow_version}`:"WORKFLOW RELEASE UNAVAILABLE";el("workflow_title").textContent=workflow.workflow_id;el("execution_id").textContent=workflow.workflow_execution_id;const usage=inspection.trace.usage??{};el("metrics").innerHTML=[["Status",workflow.status],...(workflow.recovery_required?[["Recovery required",(workflow.modules_requiring_recovery??[]).join(", ")||"yes"]]:[]),["Runs",inspection.modules.length],["Input tokens",usage.input_tokens??"unknown"],["Output tokens",usage.output_tokens??"unknown"]].map(([a,b])=>`<div class="metric"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join("");el("run_list").innerHTML=inspection.modules.map(row=>`<button class="run ${row.module_run.module_run_id===selected?"active":""}" data-run="${esc(row.module_run.module_run_id)}"><strong>${esc(row.module_run.workflow_node_id)}</strong><div class="mono muted">${esc(row.module_run.module_run_id)}</div></button>`).join("");document.querySelectorAll("[data-run]").forEach(button=>button.onclick=()=>{selected=button.dataset.run;tab="overview";render()});renderGraph();renderDetail()}
  function renderGraph(){const release=inspection.workflow_release;if(!release){el("nodes").innerHTML='<p class="empty">Frozen graph unavailable.</p>';return}const byNode=new Map;inspection.modules.forEach(row=>{const id=row.module_run.workflow_node_id;if(!byNode.has(id))byNode.set(id,[]);byNode.get(id).push(row)});el("nodes").innerHTML=release.nodes.map(node=>`<article class="node"><span class="mono muted">${esc(node.node_id)}</span><h3>${esc(node.module_release_ref??node.node_kind??"control")}</h3>${(byNode.get(node.node_id)??[]).map((row,index)=>`<button class="occurrence ${row.module_run.module_run_id===selected?"active":""}" data-occurrence="${esc(row.module_run.module_run_id)}">run ${index+1}</button>`).join("")||'<span class="muted">not executed</span>'}</article>`).join("");document.querySelectorAll("[data-occurrence]").forEach(button=>button.onclick=()=>{selected=button.dataset.occurrence;tab="overview";render()});const groups=(release.parallel_groups??[]).map(group=>`<span class="route mono">PARALLEL ${esc(group.group_id)} · ${esc(group.join_policy)} · [${group.branch_node_ids.map(esc).join(", ")}] → ${esc(group.join_node_id)}</span>`);const edges=release.edges.map(edge=>`<span class="route mono">${esc(edge.source_node_id)} · ${esc(edge.outcome_id)} → ${esc(edge.terminal?"END":edge.target_node_id)}</span>`);el("routes").innerHTML=[...groups,...edges].join("")}
  function renderDetail(){const row=moduleById();if(!row){el("content").innerHTML='<p class="empty">Select a Module Run.</p>';return}const run=row.module_run;el("selected_node").textContent=`${run.workflow_node_id} · occurrence ${row.node_occurrence_index}`;el("selected_run").textContent=run.module_run_id;document.querySelectorAll("[data-tab]").forEach(button=>button.classList.toggle("active",button.dataset.tab===tab));const decisions={evaluations:row.evaluations??[],selections:row.selections??[],resolutions:row.resolutions??[],context_events:row.context_events??[]};const hasDecisions=Object.values(decisions).some(items=>items.length);const views={overview:()=>`<div class="grid">${card("Module release",run.module_release_ref,true)}${card("Status",run.status)}${card("Input closure",run.input_closure_sha256,true)}${card("Variants",row.variants.length)}${card("Attempts",new Set([...(row.attempt_starts??[]).map(start=>start.attempt_id),...(row.attempts??[]).map(attempt=>attempt.attempt_id)]).size)}${card("Ledger position",run.source_ledger_position)}</div>`,context:()=>row.variants.map(variant=>`<details open><summary>${esc(variant.variant_id)} · ${esc(variant.execution_profile?.provider_id)} ${esc(variant.execution_profile?.model_id)}</summary>${card("Execution profile",variant.execution_profile_ref,true)}${bodyFor(variant.prompt_envelope_ref)}</details>`).join("")||'<p class="empty">No Agent context was recorded.</p>',attempts:()=>attemptView(row),output:()=>row.artifacts.filter(item=>item.direction==="output").map(item=>`<details><summary>${esc(item.logical_name)} · ${esc(item.artifact_ref)}</summary>${bodyFor(item.artifact_ref)}</details>`).join("")||'<p class="empty">No output in this export.</p>',decisions:()=>hasDecisions?`<pre>${pretty(decisions)}</pre>`:'<p class="empty">No Evaluation, Selection, Resolution, or Context event was projected for this Module Run.</p>',raw:()=>`<pre>${pretty(row)}</pre>`};el("content").innerHTML=views[tab]()}
  document.querySelectorAll("[data-tab]").forEach(button=>button.onclick=()=>{tab=button.dataset.tab;renderDetail()});render();
  </script>
</body>
</html>'''


__all__ = ["render_workflow_review_html"]
